SysDataModelXML.SQLNew:
--LINKEXECOUTPUT
-- 说明：表名/列名为占位，请按实际推送结果落库表调整。
DECLARE @MFGNUM VARCHAR(30) = '{0}';

DECLARE @JSON VARCHAR(MAX) = '#LINKPYTHON_RESULT#';

-- 逐单记录推送结果
DECLARE @ExternalCode VARCHAR(30);
DECLARE @Status VARCHAR(10);
DECLARE @YonyouCode VARCHAR(30);
DECLARE @YonyouId BIGINT;
DECLARE @Error VARCHAR(500);

DECLARE cur CURSOR FOR
  SELECT JSON_VALUE(r.value, '$.ExternalCode')
    , JSON_VALUE(r.value, '$.status')
    , JSON_VALUE(r.value, '$.yonyouCode')
    , JSON_VALUE(r.value, '$.yonyouId')
    , JSON_VALUE(r.value, '$.error')
  FROM OPENJSON(@JSON, '$.results') AS r;

OPEN cur;
FETCH NEXT FROM cur INTO @ExternalCode, @Status, @YonyouCode, @YonyouId, @Error;

WHILE @@FETCH_STATUS = 0
BEGIN
  -- 更新销售订单推送状态（占位表：TSALESORDER.PUSHSTATUS）
  UPDATE TSALESORDER
  SET PUSHSTATUS = CASE WHEN @Status = 'success' THEN 1 ELSE 2 END,
      YONYOUCODE = ISNULL(@YonyouCode, YONYOUCODE),
      YONYOUID = ISNULL(@YonyouId, YONYOUID),
      PUSHERRMSG = @Error,
      PUSHTIME = GETDATE()
  WHERE EXTERNALCODE = @ExternalCode;

  FETCH NEXT FROM cur INTO @ExternalCode, @Status, @YonyouCode, @YonyouId, @Error;
END;

CLOSE cur;
DEALLOCATE cur;

-- 返回推送汇总
SELECT JSON_VALUE(@JSON, '$.isSuccess') AS isSuccess
  , JSON_VALUE(@JSON, '$.message') AS message
  , (SELECT COUNT(*) FROM OPENJSON(@JSON, '$.results')) AS TotalCount
  , (SELECT COUNT(*) FROM OPENJSON(@JSON, '$.results') WHERE JSON_VALUE(value, '$.status') = 'success') AS SuccessCount
  , (SELECT COUNT(*) FROM OPENJSON(@JSON, '$.results') WHERE JSON_VALUE(value, '$.status') = 'failed') AS FailCount;

SysDataModelXML.CallFunction:
CALLFUNCTION~LINKPYTHON~
{
  "pyFile": "sale_order",
  "input": #LINKLEVELDATA(TSALESSOAPIM10,700,{0})#,
  "resultFormula": "销售订单推送完成.",
  "resultList":{
      "colv1":"$.isSuccess",
      "colv2":"$.message"
  },
  "resultSetValue":{
      "v1":"$.isSuccess",
      "v2":"$.message"
  },
  "resultAutoHide": true
}
